def parse_duration(text: str) -> int:
    units = {'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    seen_units = set()

    for unit, seconds in units.items():
        while unit in text:
            if unit in seen_units:
                raise ValueError(f"Duplicate unit: {unit}")
            seen_units.add(unit)
            value = int(text.split(unit)[0].strip())
            total_seconds += value * seconds
            text = text.split(unit, 1)[1].strip()

    if text.strip():
        raise ValueError("Leftover text")

    return total_seconds
